import java.util.Scanner;

public class DS_String {
    private static String rawString;
    private static String matchString;
    private static Node headNode;

    private static Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        inputString();
        constructLinkedList();
        if(matchString()) {
            System.out.println("字符串匹配！");
        } else {
            System.out.println("字符串不匹配！");
        }
    }

    private static void inputString() {
        System.out.println("请输入原始字符串：");
        rawString = scanner.nextLine();
        System.out.println("请输入待匹配字符串：");
        matchString = scanner.nextLine();
    }

    private static void constructLinkedList() {
        int remainder = rawString.length() % 4;
        int nodeNumber = remainder == 0 ? rawString.length() / 4 : rawString.length() / 4 + 1;
        for(int i = 0; i < 4 - remainder; i ++) {
            rawString = rawString + "\0";
        }
        Node currentNode = headNode = new Node("");
        for(int i = 0; i < nodeNumber; i ++) {
            currentNode.setNextNode(new Node(rawString.substring(i * 4, i * 4 + 4)));
            currentNode.getNextNode().setPreviousNode(currentNode);
            currentNode = currentNode.getNextNode();
        }
    }

    private static boolean matchString() {
        for(Node currentNode = headNode.getNextNode(); currentNode != null; currentNode = currentNode.getNextNode()) {
            for(int startIndex = 0; startIndex < 4; startIndex ++) {
                if(currentNode.getNodeString().charAt(startIndex) != matchString.charAt(0)) {
                    continue;
                }
                Node compareNode = currentNode;
                int charIndex = startIndex;
                boolean matched = true;
                for(int i = 0; i < matchString.length(); i ++) {
                    if(charIndex >= 4) {
                        compareNode = compareNode.getNextNode();
                        charIndex = 0;
                    }
                    if(compareNode.getNodeString().charAt(charIndex) != matchString.charAt(i)) {
                        matched = false;
                        break;
                    }
                    charIndex ++;
                }
                if(matched) {
                    return true;
                }
            }
        }
        return false;
    }
}

